WITH inventory_valuation AS ( SELECT i.i_category_id, i.i_category, SUM(inv.inv_quantity_on_hand * i.i_current_price) AS category_inventory_value FROM inventory inv JOIN item i ON inv.inv_item_sk = i.i_item_sk GROUP BY i.i_category_id, i.i_category ) SELECT iv.i_category_id, iv.i_category, iv.category_inventory_value, CASE WHEN iv.category_inventory_value >= 10000000 THEN 'Very High' WHEN iv.category_inventory_value >= 5000000 THEN 'High' WHEN iv.category_inventory_value >= 1000000 THEN 'Medium' ELSE 'Low' END AS value_band, RANK() OVER (ORDER BY iv.category_inventory_value DESC) AS category_rank, ROUND(iv.category_inventory_value * 100.0 / SUM(iv.category_inventory_value) OVER (), 2) AS pct_of_total_value FROM inventory_valuation iv ORDER BY category_rank
